import {expect,it} from 'vitest';
import {ARC_POLICY_SCHEMA,ARC_HORIZON_POLICY_SCHEMA,arcControlProposals} from '../scripts/v0/optimizer/arc_control_policy.ts';
import {arcFeatureDistance} from '../scripts/v0/optimizer/arc_value.ts';
import {makeRng} from '../scripts/lib/rng.ts';

const trees=Array.from({length:8},(_,feature)=>({left:[1,-1,-1],right:[2,-1,-1],
  feature:[feature,-1,-1],threshold:[.5,0,0]}));
function row(index:number,features:number[],mismatches:number){
  return {features,proximityLeaves:trees.map((_,i)=>i<mismatches?2:1),
    controlReference:{incoming:0,span:10,control:{entry:index*10,turn:0,exit:0,support:10,bias:0,offset:0}}};
}
function model(exemplars:ReturnType<typeof row>[],featureWeights?:number[]){
  return {featureSchema:ARC_POLICY_SCHEMA,featureCount:57,proximityTrees:trees,exemplars,featureWeights};
}

/** Original online neighborhood: no feature envelope or global rank bound.
 * Unique entries make adaptation and diversity selection the identity here. */
function reference(features:number[],fixture:ReturnType<typeof model>,count:number){
  const leaves=fixture.proximityTrees.map(tree=>Math.fround(features[tree.feature[0]])<=tree.threshold[0]?1:2);
  const limit=Math.max(24,count*8),retained:{distance:number;row:ReturnType<typeof row>}[]=[];
  for(const row of fixture.exemplars){
    const partition=leaves.reduce((sum,leaf,i)=>sum+Number(leaf!==row.proximityLeaves[i]),0);
    if(retained.length===limit&&partition>retained.at(-1)!.distance)continue;
    const metric=arcFeatureDistance(features,row.features,fixture.featureWeights),distance=partition+metric/(1+metric);
    if(retained.length===limit&&distance>=retained.at(-1)!.distance)continue;
    retained.push({distance,row});retained.sort((a,b)=>a.distance-b.distance);
    if(retained.length>limit)retained.pop();
  }
  return retained.slice(0,count).map(({row})=>row.controlReference.control);
}

it('matches the original neighborhood across rank distributions, metrics and row orders',()=>{
  const rng=makeRng(71823);
  for(let trial=0;trial<60;trial++){
    const query=Array.from({length:57},()=>Math.floor(rng()*2));
    const rows=Array.from({length:240},(_,i)=>row(i,query.map(v=>v+Math.floor(rng()*4)),Math.floor(rng()*9)));
    if(trial%2)rows.reverse();
    const weights=trial%3?undefined:query.map(()=>Math.floor(rng()*3));
    const fixture=model(rows,weights),count=[1,3,8,32][trial%4];
    expect(arcControlProposals(query,0,10,fixture,count)).toEqual(reference(query,fixture,count));
  }
});

it('retains stable cross-partition ties when a finite distance fraction rounds to one',()=>{
  const query=Array(57).fill(0),far=query.map(()=>1e20);
  const fixture=model([row(0,query,1),...Array.from({length:30},(_,i)=>row(i+1,far,0)),
    ...Array.from({length:40},(_,i)=>row(i+31,query,8))]);
  expect(arcControlProposals(query,0,10,fixture,1)).toEqual([fixture.exemplars[0].controlReference.control]);
  for(const weights of [undefined,Array(57).fill(0),Array(57).fill(Number.MIN_VALUE)]){
    fixture.featureWeights=weights;
    expect(arcControlProposals(query,0,10,fixture,3)).toEqual(reference(query,fixture,3));
  }
});

it('preserves unordered and overflowing distances, and refreshes replaced model inputs',()=>{
  for(const value of [NaN,Infinity,-Infinity,Number.MAX_VALUE,1e154,Number.MIN_VALUE]){
    const query=Array(57).fill(0),rows=Array.from({length:80},(_,i)=>row(i,query.slice(),i<40?8:0));
    rows[0].features[0]=value;
    for(const weights of [undefined,Array(57).fill(0),Array(57).fill(Number.MAX_VALUE)]){
      const fixture=model(rows,weights);
      expect(arcControlProposals(query,0,10,fixture,3)).toEqual(reference(query,fixture,3));
    }
  }
  const query=Array(57).fill(0),fixture=model(Array.from({length:80},(_,i)=>row(i,query.slice(),i%9)));
  arcControlProposals(query,0,10,fixture,1);
  fixture.exemplars=fixture.exemplars.toReversed().map(r=>({...r,features:query.map(()=>1e300)}));
  expect(arcControlProposals(query,0,10,fixture,3)).toEqual(reference(query,fixture,3));
  fixture.proximityTrees=trees.map(t=>({...t,threshold:[-.5,0,0]}));
  expect(arcControlProposals(query,0,10,fixture,3)).toEqual(reference(query,fixture,3));
  fixture.featureSchema=ARC_HORIZON_POLICY_SCHEMA;fixture.featureCount=67;
  fixture.exemplars=fixture.exemplars.map(r=>({...r,features:r.features.concat(Array(10).fill(0))}));
  const extended=query.concat(Array(10).fill(1e300));
  expect(arcControlProposals(extended,0,10,fixture,3)).toEqual(reference(extended,fixture,3));

  // A width change must refresh bounds even when both model arrays stay put.
  const wide=model(Array.from({length:80},(_,i)=>row(i,Array(67).fill(0),i<40?8:0)));
  wide.exemplars[0].features[66]=1e300;
  arcControlProposals(query,0,10,wide,3);
  wide.featureSchema=ARC_HORIZON_POLICY_SCHEMA;wide.featureCount=67;
  const zeros=Array(67).fill(0);
  expect(arcControlProposals(zeros,0,10,wide,3)).toEqual(reference(zeros,wide,3));
  const missing=model(wide.exemplars.map((r,i)=>i===0?{...r,features:[]}:r));
  expect(arcControlProposals(query,0,10,missing,3)).toEqual(reference(query,missing,3));
});

